/**
 * Compute change severity based on change type and content delta size.
 */
export function computeSeverity(
  changeType: "added" | "removed" | "modified",
  bodyDelta: number,
  priorityChanged: boolean,
  typeChanged: boolean,
): "critical" | "high" | "medium" | "low" {
  if (changeType === "removed") return "high";
  if (changeType === "added") {
    return bodyDelta > 500 ? "medium" : "low";
  }
  if (typeChanged || priorityChanged) return "high";
  if (bodyDelta > 300) return "medium";
  return "low";
}

export function estimateUsageCostUsd(
  model: string,
  usage: Pick<TokenUsage, "promptTokens" | "completionTokens" | "cacheReadTokens" | "cacheWriteTokens">,
  provider: ProviderKey,
  writeTtl: PromptCacheTtl = "5m",
): number {
  const norm = normalizeTokenUsage({ ...usage, totalTokens: 0 }, conventionForProvider(provider));
  const cacheWriteMultiplier =
    provider === "anthropic" && writeTtl === "1h"
      ? CACHE_WRITE_MULTIPLIER_1H
      : CACHE_WRITE_MULTIPLIER_5M;
  return estimateCostUsd(model, norm.freshInputTokens, usage.completionTokens, {
    cacheReadTokens: norm.cacheReadTokens,
    cacheWriteTokens: norm.cacheWriteTokens,
    cacheWriteMultiplier,
  });
}

